          "qt": "<span class=\"qt-context\"><span class=\"series-label\">連問 1/2</span>64 歳の男性。腹部膨満を主訴に来院した。<br/>現病歴：1 か月前から腹部膨満が出現した。2 週間前からズボンのベルトがきつくなるのを自覚し、症状が徐々に増<br/>悪するため受診した。排便回数は1 回/ 日、普通便で、特に変化を認めない。<br/>既往歴：40 歳時から高血圧症のため内服治療中。食物や薬物のアレルギー歴はない。<br/>生活歴：食品会社の事務職。喫煙は10 本/ 日を10 年間。飲酒は日本酒1 合/ 日を30 年間。妻と2 人暮らし。3 か<br/>月前から猫を飼っている。6 か月前に東南アジアに出張した。<br/>家族歴：父が70 歳時に大腸癌のため手術。<br/>現　症：意識は清明。身長164cm、体重64kg。体温36.8℃。脈拍72/ 分、整。血圧136/78mmHg。呼吸数12/ 分。<br/>SpO2 97％（room air）。眼瞼結膜と眼球結膜とに異常を認めない。頸静脈の怒張を認めない。甲状腺と頸部リンパ<br/>節を触知しない。心音と呼吸音とに異常を認めない。腹部は膨隆。腸雑音はやや亢進。血管雑音を聴取しない。圧<br/>痛はなく、筋性防御を認めない。明らかな腫瘤を認めない。波動を認める。Traube 三角の打診は鼓音である。体<br/>位変換によりshifting dullness を認める。肋骨脊柱角の叩打痛を認めない。四肢に浮腫を認めない。<br/>検査所見：尿所見：蛋白（－）、糖（－）、潜血（－）。血液所見：赤血球436 万、Hb 13.7g/dL、Ht 41％、白血<br/>球5,400、血小板18 万、PT-INR 1.0（基準0.9 ～1.1）。血液生化学所見：総蛋白7.6g/dL、アルブミン3.8g/dL、<br/>総ビリルビン1.8mg/dL、直接ビリルビン0.9mg/dL、AST 42U/L、ALT 46U/L、LD 256U/L（基準124 ～222）、<br/>ALP 126U/L（基準38 ～113）、γ-GT 108U/L（基準13 ～64）、アミラーゼ94U/L（基準44 ～132）、尿素窒素<br/>18mg/dL、クレアチニン0.9mg/dL、尿酸6.9mg/dL、血糖102mg/dL、HbA1c 6.0％（基準4.9 ～6.0）、総コレステロー<br/>ル180mg/dL、トリグリセリド108mg/dL、Na 131mEq/L、K 4.4mEq/L、Cl 97mEq/L。CRP 1.0mg/dL。</span><br/><strong>身体診察から予想されるのはどれか。</strong>",
