          "qt": "<span class=\"qt-context\"><span class=\"series-label\">連問 1/2</span>61 歳の男性。腹部膨満感と意識障害とを主訴に家族に連れられて来院した。<br/>現病歴：3 か月前から全身倦怠感を自覚していた。1 か月前から食欲低下と下腿の浮腫とがあり、2 週前から腹部膨満<br/>感とふらつきも出現して外出ができなくなった。本日朝から発熱を認め、傾眠状態となったため家族に連れられて<br/>受診した。<br/>既往歴：47 歳時に人間ドックで肝機能異常と耐糖能異常とを指摘されたが医療機関を受診していなかった。<br/>生活歴：喫煙は20 本/ 日を40 年間。脚本家で、若い頃から飲酒をしながら深夜まで仕事をするのが習慣化している。<br/>家族歴：母親が脳出血で死亡。<br/>現　症：意識レベルはJCSⅠ-2。身長169cm、体重79kg。体温37.9℃。脈拍84/ 分、整。血圧134/78mmHg。呼吸<br/>数16/ 分。SpO2 98％（room air）。眼瞼結膜は貧血様である。眼球結膜に黄染を認める。呼気にアンモニア臭を<br/>認める。心音と呼吸音とに異常を認めない。腹部は膨隆しているが軟で、波動を認める。圧痛と筋性防御とを認め<br/>ない。直腸指診で黒色便の付着を認める。四肢に運動麻痺はなく、下腿に浮腫を認める。<br/>検査所見：血液所見：赤血球328 万、Hb 8.8g/dL、Ht 27％、白血球9,500（桿状核好中球31％、分葉核好中球44％、<br/>好酸球1％、好塩基球1％、単球6％、リンパ球17％）、血小板9 万、PT 48％（基準80 ～120）。血液生化学所見：<br/>総蛋白6.4g/dL、アルブミン2.5g/dL、総ビリルビン6.9mg/dL、直接ビリルビン4.7mg/dL、AST 118IU/L、ALT<br/>96IU/L、LD 377IU/L（基準176 ～353）、ALP 683IU/L（基準115 ～359）、γ-GTP 332IU/L（基準8 ～50）、アミラー<br/>ゼ50IU/L（基準37 ～160）、尿素窒素52mg/dL、クレアチニン1.1mg/dL、尿酸6.9mg/dL、血糖100mg/dL、<br/>HbA1c 7.3％（基準4.6 ～6.2）、総コレステロール156mg/dL、トリグリセリド90mg/dL、Na 131mEq/L、K 4.5mEq/L、<br/>Cl 96mEq/L。CRP 2.4mg/dL。頭部CT で異常を認めない。腹部造影CT を示す。</span><br/><strong>この患者に認められる可能性が高いのはどれか。</strong>",
