          "qt": "<span class=\"qt-context\"><span class=\"series-label\">連問 2/2</span>78 歳の男性。意識障害のため搬入された。<br/>現病歴：7 日前から上腹部の鈍痛と38.3℃の発熱とがみられていた。6 日前にかかりつけの診療所を受診し、解熱薬<br/>を処方された。5 日前、症状が軽快したため、薬の内服を中止した。2 日前から再び右上腹部痛を自覚し、37.6℃<br/>の発熱と全身倦怠感とがみられた。昨日から食欲低下と悪寒とを伴うようになったため、中断していた解熱薬の内<br/>服を再開した。昨日の時点で、尿の色が濃いことに気付いていた。本日、起床後に悪寒と悪心とが出現し、意識が<br/>もうろうとした状態となった。家族の問いかけに対してつじつまの合わない返答がみられたため、家族が救急車を<br/>要請した。<br/>既往歴：7 年前から高血圧症に対しアンジオテンシン変換酵素阻害薬を内服中。3 年前に腹部超音波検査で3、4 個の<br/>胆石を指摘された。<br/>生活歴：喫煙は15 本/ 日を58 年間。飲酒は日本酒2 合/ 日を58 年間。<br/>家族歴：父親が脳出血で死亡。<br/>現　症：意識レベルはJCSⅡ-10。身長164cm、体重59kg。体温39.0℃。心拍数112/ 分、整。血圧82/58mmHg。呼<br/>吸数24/ 分。SpO2 97％（3ℓ/ 分酸素投与下）。眼球結膜に黄染を認める。心音と呼吸音とに異常を認めない。腹<br/>部はやや膨隆し、軟で、肝・脾を触知しない。右季肋部を中心に圧痛を認める。</span><br/><strong>この患者の循環状態の重症度を評価するための検査で適切なのはどれか。</strong>",
